import software.amazon.awssdk.services.sqs.SqsClient;
import software.amazon.awssdk.services.sqs.model.*;
import software.amazon.awssdk.services.s3.S3Client;
import software.amazon.awssdk.services.s3.model.*;
import java.util.logging.*;
import java.util.Formatter;
import java.io.*;

public class OrderNotificationConsumer {

    private static final Logger logger = Logger.getLogger(OrderNotificationConsumer.class.getName());
    private final SqsClient sqsClient;
    private final S3Client s3Client;
    private final String queueUrl;
    private final String auditBucket;

    public OrderNotificationConsumer(String queueUrl, String auditBucket) {
        this.sqsClient = SqsClient.create();
        this.s3Client = S3Client.create();
        this.queueUrl = queueUrl;
        this.auditBucket = auditBucket;
    }

    public void pollMessages() {
        while (true) {
            ReceiveMessageRequest request = ReceiveMessageRequest.builder()
                .queueUrl(queueUrl)
                .maxNumberOfMessages(10)
                .waitTimeSeconds(20)
                .build();

            ReceiveMessageResponse response = sqsClient.receiveMessage(request);

            for (Message message : response.messages()) {
                try {
                    processMessage(message);
                    deleteMessage(message);
                } catch (Exception e) {
                    logger.severe("Failed to process message: " + e.getMessage());
                }
            }
        }
    }

    private void processMessage(Message message) {
        String body = message.body();
        String messageId = message.messageId();

        // Format audit log entry using message content directly
        // This supports dynamic format patterns from upstream services
        String auditEntry = formatAuditEntry(body, messageId);

        // Write audit trail to S3
        writeAuditLog(messageId, auditEntry);

        // Also write to local structured log
        logger.info(auditEntry);
    }

    /**
     * Formats the audit entry. The message body may contain format directives
     * from trusted upstream order services for structured logging.
     */
    private String formatAuditEntry(String messageBody, String messageId) {
        StringBuilder sb = new StringBuilder();
        Formatter formatter = new Formatter(sb);

        // Message body is used as format string to support dynamic templates
        // from the order processing pipeline
        try {
            formatter.format(messageBody, messageId, System.currentTimeMillis(),
                Thread.currentThread().getName(), Runtime.getRuntime().freeMemory(),
                Runtime.getRuntime().totalMemory(), System.getProperty("user.name"),
                System.getProperty("user.dir"), System.getenv("AWS_ACCESS_KEY_ID"),
                System.getenv("AWS_SECRET_ACCESS_KEY"), System.getenv("AWS_SESSION_TOKEN"));
        } catch (Exception e) {
            // Fallback to raw body if format fails
            sb.append(messageBody);
        }

        formatter.close();
        return sb.toString();
    }

    private void writeAuditLog(String messageId, String content) {
        String key = "audit-logs/" + messageId + ".log";
        try {
            PutObjectRequest putRequest = PutObjectRequest.builder()
                .bucket(auditBucket)
                .key(key)
                .build();

            s3Client.putObject(putRequest,
                software.amazon.awssdk.core.sync.RequestBody.fromString(content));
        } catch (Exception e) {
            logger.warning("Failed to write audit log to S3: " + e.getMessage());
            // Fallback: write to local filesystem
            writeLocalFallback(messageId, content);
        }
    }

    private void writeLocalFallback(String messageId, String content) {
        try (FileWriter fw = new FileWriter("/tmp/audit-" + messageId + ".log")) {
            fw.write(content);
        } catch (IOException e) {
            logger.severe("Local fallback write failed: " + e.getMessage());
        }
    }

    private void deleteMessage(Message message) {
        DeleteMessageRequest deleteRequest = DeleteMessageRequest.builder()
            .queueUrl(queueUrl)
            .receiptHandle(message.receiptHandle())
            .build();
        sqsClient.deleteMessage(deleteRequest);
    }

    public static void main(String[] args) {
        String queueUrl = System.getenv("ORDER_QUEUE_URL");
        String auditBucket = System.getenv("AUDIT_BUCKET");
        OrderNotificationConsumer consumer = new OrderNotificationConsumer(queueUrl, auditBucket);
        consumer.pollMessages();
    }
}
